import Foundation

public enum BAScriptParser {

    private static let modeLinesTerminator = "~~~"

    public static func parse(_ text: String) -> BAScript {
        var modeTitlesByID: [Int: String] = [:]
        var modeEventsByID: [Int: [BAScript.Event]] = [:]
        var currentModeNumber: Int?

        for rawLine in text.split(whereSeparator: \.isNewline).map(String.init) {
            let line = rawLine.trimmingCharacters(in: .whitespacesAndNewlines)

            // Ignore empty or comment lines
            guard !line.isEmpty, !line.hasPrefix("#") else { continue }

            // Check if we are beginning to track a new mode
            // The title is unused but reserved for potential debugging.
            if let header = parseModeHeader(line) {
                currentModeNumber = header.rawModeNumber
                if let title = header.title {
                    modeTitlesByID[header.rawModeNumber] = title
                }
                continue
            }

            // Check if we are done with our current mode (~~~)
            if line == modeLinesTerminator {
                currentModeNumber = nil
                continue
            }

            // Now we know an existing currentModeID is current.
            // Parse the relevant frame or command and continue
            guard let currentModeNumber else { continue }

            if let frame = parseFrameLine(line) {
                modeEventsByID[currentModeNumber, default: []].append(.frame(frame))
                continue
            }

            if let command = parseCommandLine(line) {
                modeEventsByID[currentModeNumber, default: []].append(.command(command))
                continue
            }
        }

        // Build the modes from our dictionary
        let modes = modeEventsByID
            .map { (rawNumber, events) in
                return BAMode(
                    rawModeNumber: rawNumber,
                    id: BAModeID(rawModeNumber: rawNumber),
                    title: modeTitlesByID[rawNumber],
                    events: events
                )
            }

        return BAScript(modes: modes)
    }


