    private struct ModeHeader {
        let rawModeNumber: Int
        let title: String?
    }

    private static func parseModeHeader(_ line: String) -> ModeHeader? {
        guard line.hasPrefix("///") else { return nil }

        let parts = splitComment(line)
        let body = parts.body

        guard let range = body.range(of: "Mode ") else { return nil }

        let afterMode = body[range.upperBound...]
        let numberText = afterMode
            .prefix { $0.isNumber }

        guard let number = Int(numberText) else { return nil }

        return ModeHeader(
            rawModeNumber: number,
            title: parts.comment
        )
    }

    private static func parseCommandLine(_ line: String) -> BAScript.Command? {
        let parts = splitComment(line)
        let body = parts.body.trimmingCharacters(in: .whitespacesAndNewlines)

        guard body.hasPrefix("C") else { return nil }

        return BAScript.Command(
            code: body,
            comment: parts.comment
        )
    }

    private static func parseFrameLine(_ line: String) -> BAScript.FrameReference? {
        let partsWithoutComment = splitComment(line).body
        let parts = partsWithoutComment.split(separator: " ", omittingEmptySubsequences: true)

        guard parts.count >= 3 else { return nil }
        guard let ticks = Int(parts[0]) else { return nil }

        let flags = String(parts[1])
        let filename = String(parts[2])

        guard filename.lowercased().hasSuffix(".png") else { return nil }

        return BAScript.FrameReference(
            durationTicks: ticks,
            flags: flags,
            filename: filename
        )
    }

    private static func splitComment(_ line: String) -> (body: String, comment: String?) {
        let pieces = line.split(separator: "#", maxSplits: 1, omittingEmptySubsequences: false)

        let body = String(pieces[0])
            .trimmingCharacters(in: .whitespacesAndNewlines)

        let comment = pieces.count > 1
        ? String(pieces[1]).trimmingCharacters(in: .whitespacesAndNewlines)
        : nil

        return (body, comment?.isEmpty == true ? nil : comment)
    }

